"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["984"],{78701(e){e.exports=JSON.parse('{"id":"FIN-1100","slug":"expansion-option","term":"Expansion Option","also_known_as":[],"difficulty":"Advanced","definition":"An expansion option is a company\'s ability to scale up a project or investment in future if conditions turn out to be favourable, such as demand proving stronger than expected.","explanation":["The expansion option is a type of real option. It gives the company the potential to benefit from good outcomes without having to commit the full investment upfront.","For example, a retailer opens a pilot store in a new country. If it succeeds, the company can open dozens more stores there. The pilot store may have a low or even negative net present value on its own, but the opportunity to expand if it succeeds can make the overall decision worthwhile.","Expansion options are common in new markets, research and development, technology platforms and natural resources. Pharmaceutical research, for instance, creates options to develop products further if early trials succeed.","Expansion options are valuable when uncertainty is high and the potential upside is large. Companies can create them deliberately, for example by buying extra land, designing facilities that can be enlarged or building platforms that can support future products. The difficulty lies in estimating their value, which relies on assumptions about future uncertainty."],"note":"","total":1500,"prev":{"slug":"expansion","term":"Expansion"},"next":{"slug":"expected-return","term":"Expected Return"}}')}}]);